L34_1.m_Talk_KOREA = "워낙 신출귀몰해서 쉽진 않을 거예요. 도시의 카메라들을 전부 뒤져도 녀석을 못 찾았으니까요."
L34_1.m_fTalkTime = 0.03
L34_1.m_Talk_JPN = "神出鬼没ですからそう簡単には捕まらないと思います。都市のカメラをすべて確認しても見つけられませんでした。"
L34_1.m_Talk_ENG = "She's incredibly elusive, so it won't be simple. Even after checking all the city cameras, we couldn't track her down."
L34_1.m_Talk_TWN = "她神出鬼沒的，不太好找。我們已經翻遍了城市的所有監視器，也沒能找到她。"
L34_1.m_Talk_SCN = "他神出鬼没的，不太好找。即使翻遍了城市的所有摄像头，也没能找到他。"
L34_1.m_Talk_DEU = "She's incredibly elusive, so it won't be simple. Even after checking all the city cameras, we couldn't track her down."
L34_1.m_Talk_FRA = "She's incredibly elusive, so it won't be simple. Even after checking all the city cameras, we couldn't track her down."
