L21_1 = "괜찮아. 오히려 잘 됐어요. 거짓말이면 아무도 아프지 않은 거니까."
L20_1.m_Talk_KOREA = L21_1
L20_1.m_fTalkTime = 0.03
L21_1 = "大丈夫。むしろよかったです。ウソだったなら誰も痛くなかったってことですから。"
L20_1.m_Talk_JPN = L21_1
L21_1 = "It's okay. It's actually a good thing. If it's a lie, no one is sick."
L20_1.m_Talk_ENG = L21_1
L21_1 = "沒關係，這樣反倒更好。如果是說謊，就說明沒有人真的生病受苦不是嘛。"
