L13_1 = "그거 맞고 나서 며칠 동안은 멀쩡했잖아! 내가 그것만 계속 구해주면 언젠가 나을 거라고!"
L12_1.m_Talk_KOREA = L13_1
L12_1.m_fTalkTime = 0.03
L13_1 = "それを打ってもらってから何日かは元気だったよね！　ずっとそれが手に入れば、いつかは治るよ！"
L12_1.m_Talk_JPN = L13_1
L13_1 = "You were fine for a few days after taking that! If I keep bringing it, you'll get better eventually!"
L12_1.m_Talk_ENG = L13_1
L13_1 = "你用了那個藥後不是好了很多天嗎？只要我能再多找些藥，遲早能治好的！"
L12_1.m_Talk_TWN = L13_1
L13_1 = "你用了那个药后不是好了很多天吗？只要我能再多找些药，迟早能治好的！"
