L43_1 = "침식증후군은 치료할 수 없어. 돈 많은 재벌도, 권위 있는 대통령도 못 고치는 병이야."
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "侵食症候群は治療できない。お金持ちの財閥も、権威のある大統領も治せない病なの。"
L42_1.m_Talk_JPN = L43_1
L43_1 = "Corruption Syndrome is incurable. No amount of money or power can fix it."
L42_1.m_Talk_ENG = L43_1
L43_1 = "侵蝕症候群是無法治癒的病，就算是富可敵國的財閥，或者位高權重的總統也束手無策。"
L42_1.m_Talk_TWN = L43_1
L43_1 = "侵蚀症候群是无法治愈的病，就算是富可敌国的财阀，或者位高权重的总统也束手无策。"
L42_1.m_Talk_SCN = L43_1
L43_1 = "Corruption Syndrome is incurable. No amount of money or power can fix it."
