L43_1.m_Pos = "C"
L44_1 = "넌 지금 밑 빠진 독에 물을 붓고 있는 거라고. 네 인생을 망쳐가면서까지."
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "あなたは今意味のないことをしているのよ。自分の人生をダメにしてまで。"
L43_1.m_Talk_JPN = L44_1
L44_1 = "Right now, you're just trying to fill a bottomless pit, ruining your life in the process."
L43_1.m_Talk_ENG = L44_1
L44_1 = "你就像拼命往破碎的罐子裡注水的人，甚至不惜為此毀掉你的人生。"
L43_1.m_Talk_TWN = L44_1
