L51_1 = "OLDWOMAN_NPC_WITH_ANNIE"
L50_1.m_CharStrID = L51_1
L51_1 = "넌 워치도 있는 카운터잖니. 나 같은 집도 연줄도 없는 부랑자를 돌보느라 네 삶을 망치지 마."
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "あなたはウォッチも持っているカウンターじゃない。私みたいに家もコネもないホームレスの面倒を見るためにあなたの人生を台無しにしないで。"
L50_1.m_Talk_JPN = L51_1
L51_1 = "You're a Counter with a Watch, aren't you? Don't ruin your life taking care of someone like me, a homeless nobody with no connections."
L50_1.m_Talk_ENG = L51_1
L51_1 = "你可是有能量環的制裁者。別為了照顧像我這樣無家可歸、毫無背景的流浪者而毀了自己的人生。"
L50_1.m_Talk_TWN = L51_1
L51_1 = "你可是有能量环的制裁者。别为了照顾像我这样无家可归、毫无背景的流浪者而毁了自己的人生。"
L50_1.m_Talk_SCN = L51_1
